class AsyncAurixClient:
    """`asyncio` façade over `AurixClient`: every call runs the blocking request in a worker thread."""

    def __init__(self, client: AurixClient):
        self.sync = client

    async def _run(self, fn: Any, *args: Any, **kwargs: Any) -> Any:
        import asyncio
        import functools

        loop = asyncio.get_running_loop()
        return await loop.run_in_executor(None, functools.partial(fn, *args, **kwargs))

    async def health(self, *, options: Optional[RequestOptions] = None) -> "T.Health":
        """Liveness and basic counters


        `GET /health`
        """
        return await self._run(self.sync.health, options=options)  # type: ignore[no-any-return]

    async def ready(self, *, options: Optional[RequestOptions] = None) -> "T.Ready":
        """Readiness (database and Redis reachable)


        `GET /ready`
        """
        return await self._run(self.sync.ready, options=options)  # type: ignore[no-any-return]

    async def openapi(self, *, options: Optional[RequestOptions] = None) -> Dict[str, Any]:
        """This document


        `GET /openapi.json`
        """
        return await self._run(self.sync.openapi, options=options)  # type: ignore[no-any-return]

    async def admin_setup(self, body: "T.BootstrapAdminRequest", *, options: Optional[RequestOptions] = None) -> "T.Admin":
        """Bootstrap the first superadmin


        Allowed only while no administrator exists, or when `X-Bootstrap-Token` matches
        `auth.bootstrap_token`. Rate-limited by client IP.

        `POST /admin/setup`
        Auth: BootstrapToken.
        """
        return await self._run(self.sync.admin_setup, body, options=options)  # type: ignore[no-any-return]

    async def admin_login(self, body: "T.AdminLoginRequest", *, options: Optional[RequestOptions] = None) -> "T.AdminLoginResponse":
        """Exchange email + password for an admin JWT


        `POST /admin/login`
        """
        return await self._run(self.sync.admin_login, body, options=options)  # type: ignore[no-any-return]

    async def admin_auth_methods(self, *, options: Optional[RequestOptions] = None) -> "T.AdminAuthMethods":
        """Sign-in methods offered by this deployment


        For login pages: whether password login is on and whether (and where) SSO starts.

        `GET /admin/auth/methods`
        """
        return await self._run(self.sync.admin_auth_methods, options=options)  # type: ignore[no-any-return]

    async def admin_oidc_callback(self, *, code: Optional[str] = None, state: Optional[str] = None, error: Optional[str] = None, error_description: Optional[str] = None, options: Optional[RequestOptions] = None) -> "T.AdminOidcCallbackResponse":
        """SSO callback (identity provider redirect target)


        Verifies `state` (encrypted, single-use, bound to the login cookie, expires after
        `auth.oidc.state_ttl_secs`), exchanges `code` (PKCE), validates the ID token (signature via the
        provider's JWKS, `iss`, `aud`, `nonce`, `exp`, email verification, allowed domains) and maps the
        provider's groups to a role. With `auth.oidc.frontend_redirect` set, the browser is sent there
        with `#token=…&expires_in_secs=…[&return_to=…]` (or `#error=…&error_description=…`); otherwise
        the token is returned as JSON. The login cookie is cleared either way. Roles come from
        `auth.oidc.superadmin_emails`, then the highest role in `role_mapping` matched by the groups
        claim, then `default_role`; identities that resolve to no role are refused (`403`).

        `GET /admin/oidc/callback`
        """
        return await self._run(self.sync.admin_oidc_callback, code=code, state=state, error=error, error_description=error_description, options=options)  # type: ignore[no-any-return]

