    async def mixdown_recordings(self, body: "T.MixdownRecordingsRequest", *, options: Optional[RequestOptions] = None) -> "T.Recording":
        """Render a channel mixdown from participant tracks


        Combines finished per-participant tracks of one channel (aligned on `audio_started_at`, summed
        with soft clipping) into a single Ogg/Opus or WAV file. Returns the new recording with `kind =
        mixdown` and `status = processing`; it becomes `ready` asynchronously — poll `GET
        /v1/recordings/{id}` or subscribe to `recording.processed`. The job runs on the node that
        accepted the request, which must be able to read every source (its own files or object storage);
        otherwise 409 names the node holding the track. 429 when this node's processing queue
        (`recording.processing.max_queued`) is full.

        `POST /v1/recordings/mixdown`
        Auth: ApiKeyHeader | ApiKeyBearer.
        Permissions: recordings:write.
        """
        return await self._run(self.sync.mixdown_recordings, body, options=options)  # type: ignore[no-any-return]

    async def transcribe_recording(self, recording_id: str, *, options: Optional[RequestOptions] = None) -> "T.RecordingTranscript":
        """Queue speech-to-text of a stored recording


        Requires an `[stt]` provider on the node. A participant track is transcribed as one speaker; a
        mixdown is transcribed from its source tracks one by one, so every segment names its speaker.
        Audio is decoded in `recording.processing.stt_chunk_secs` chunks cut on silence and resampled to
        `stt_sample_rate`. Returns the transcript row with `status = queued`; poll `GET .../transcript`
        or wait for `recording.processed` with `job = transcript`. 409 while a transcript of this
        recording is already queued/running or the recording is not `ready`; a `failed` transcript may
        be requested again.

        `POST /v1/recordings/{recording_id}/transcribe`
        Auth: ApiKeyHeader | ApiKeyBearer.
        Permissions: recordings:write.
        """
        return await self._run(self.sync.transcribe_recording, recording_id, options=options)  # type: ignore[no-any-return]

    async def get_recording_transcript(self, recording_id: str, *, format: Optional["T.GetRecordingTranscriptFormat"] = None, options: Optional[RequestOptions] = None) -> "T.RecordingTranscript":
        """Transcript of a recording (JSON, SRT or WebVTT)


        `format=json` (default) returns the row in any state; `srt`/`vtt` render the segments as
        subtitles (speaker as a `<v uuid>` voice tag) and require `status = ready` (409 otherwise).

        `GET /v1/recordings/{recording_id}/transcript`
        Auth: ApiKeyHeader | ApiKeyBearer.
        Permissions: recordings:read.

        When the server answers with application/x-subrip, text/vtt (non-JSON `format`) this call fails; use the `get_recording_transcript_raw` instead.
        """
        return await self._run(self.sync.get_recording_transcript, recording_id, format=format, options=options)  # type: ignore[no-any-return]

    async def get_recording_transcript_raw(self, recording_id: str, *, format: Optional["T.GetRecordingTranscriptFormat"] = None, options: Optional[RequestOptions] = None) -> RawResponse:
        """Transcript of a recording (JSON, SRT or WebVTT)


        `format=json` (default) returns the row in any state; `srt`/`vtt` render the segments as
        subtitles (speaker as a `<v uuid>` voice tag) and require `status = ready` (409 otherwise).

        `GET /v1/recordings/{recording_id}/transcript`
        Auth: ApiKeyHeader | ApiKeyBearer.
        Permissions: recordings:read.

        Returns the raw body (application/json, application/x-subrip, text/vtt).
        """
        return await self._run(self.sync.get_recording_transcript_raw, recording_id, format=format, options=options)  # type: ignore[no-any-return]

    async def list_user_read_markers(self, user_id: str, *, channel_id: Optional[str] = None, peer_user_id: Optional[str] = None, options: Optional[RequestOptions] = None) -> Union["T.ReadMarkerStatus", "T.ListUserReadMarkersResponseVariant1"]:
        """Read markers of a user


        With `channel_id` or `peer_user_id`: the user's marker in that conversation (`null` if they
        never read there) and how many messages from others lie after it (capped at
        `chat.unread_count_cap`). Without a selector: every marker of the user. Requires `chat.persist =
        true` (otherwise `404`).

        `GET /v1/users/{user_id}/read-markers`
        Auth: ApiKeyHeader | ApiKeyBearer.
        Permissions: chat:read.
        """
        return await self._run(self.sync.list_user_read_markers, user_id, channel_id=channel_id, peer_user_id=peer_user_id, options=options)  # type: ignore[no-any-return]

    async def put_user_read_marker(self, user_id: str, body: "T.ReadMarkerRequest", *, options: Optional[RequestOptions] = None) -> "T.PutUserReadMarkerResponse":
        """Advance a user's read marker


        Marks everything in the conversation up to `message_id` as read on the user's behalf (for
        example after a support agent answered for them). Markers only move forward: an older or equal
        position is accepted but `moved` is `false`. The message must belong to the selected
        conversation of that user, otherwise `404`. Every device of the user receives `ChatReadMarker`;
        with `chat.read_receipts` so do the channel members / the peer. Requires `chat.persist = true`.

        `PUT /v1/users/{user_id}/read-markers`
        Auth: ApiKeyHeader | ApiKeyBearer.
        Permissions: chat:write.
        """
